robo-advisor.pseudocode:
def rebalance(holdings, target, prices, band=0.05):
    # target: 자산별 목표 비중 {자산: 비율}
    total = sum(holdings[a] * prices[a] for a in holdings)
    orders = {}
    for a in target:
        cur_val = holdings[a] * prices[a]
        cur_w = cur_val / total  # 현재 비중
        if abs(cur_w - target[a]) > band:  # 허용밴드 초과
            target_val = total * target[a]
            diff = target_val - cur_val
            orders[a] = diff / prices[a]  # 매수(+)·매도(-)
    return orders

rolling-deployment.pseudocode:
def rolling_deploy(servers, new_ver, batch_size, lb):
    done = []
    for i in range(0, len(servers), batch_size):
        batch = servers[i:i + batch_size]
        for s in batch:
            lb.drain(s)  # 신규 트래픽 차단, 처리 중 요청 완료
            s.install(new_ver)
            s.restart()
        if not all(s.health_check() for s in batch):
            # 실패: 진행 중단, 교체한 서버 모두 원복
            for s in done + batch:
                s.install(s.prev_ver)
                s.restart()
                lb.enable(s)
            return 'rollback'
        for s in batch:
            lb.enable(s)  # 트래픽 복귀 (신구 버전 공존)
        done += batch
    return 'success'

root-finding.pseudocode:
def bisection(f, a, b, tol=1e-10):
    assert f(a) * f(b) < 0  # 부호 변화 → 구간 안에 근 존재
    while b - a > tol:
        m = (a + b) / 2
        if f(a) * f(m) <= 0:  # 근이 왼쪽 반에 있음
            b = m
        else:
            a = m
    return (a + b) / 2

def newton(f, df, x, tol=1e-12, max_iter=50):
    for _ in range(max_iter):
        step = f(x) / df(x)  # 접선의 x절편으로 이동
        x -= step
        if abs(step) < tol:
            return x
    raise ValueError('수렴 실패: 초기값 재선정')

roulette-wheel-selection.pseudocode:
def roulette_select(pop, fitness):
    total = sum(fitness)  # 적합도는 0 이상이어야 함
    r = uniform(0, total)  # 룰렛 회전
    acc = 0.0
    for ind, f in zip(pop, fitness):
        acc += f  # 적합도 비례 구간 누적
        if r <= acc:
            return ind
    return pop[-1]  # 부동소수 오차 대비

parents = [roulette_select(pop, fit) for _ in pop]

round-function.pseudocode:
def feistel_encrypt(block, round_keys, F):
    # block을 좌우 절반으로 분할
    L, R = split_half(block)
    for k in round_keys:
        L, R = R, L ^ F(R, k)  # 라운드: 오른쪽에 F 적용
    return R + L  # 마지막 라운드 후 교환하지 않음

def feistel_decrypt(block, round_keys, F):
    # 라운드 키를 역순으로 적용하면 복호
    R, L = split_half(block)
    for k in reversed(round_keys):
        R, L = L, R ^ F(L, k)
    return L + R

round-robin-scheduling.pseudocode:
def round_robin(bursts, q):
    # bursts: {pid: CPU 실행시간}, 모두 0시점 도착 가정
    queue = list(bursts)  # FIFO 준비 큐
    remain = dict(bursts)
    t, finish = 0, {}
    while queue:
        p = queue.pop(0)
        run = min(q, remain[p])  # 최대 퀀텀만큼 실행
        t += run
        remain[p] -= run
        if remain[p] == 0:
            finish[p] = t  # 완료 시각
        else:
            queue.append(p)  # 선점 후 큐 맨 뒤로
    return finish

routing-information-protocol.pseudocode:
INF = 16  # 홉 수 16 = 도달 불가

def on_update(table, neighbor, adv):
    # table[dst] = (홉 수, 다음 홉), adv = 이웃 광고 {dst: 홉 수}
    for dst, m in adv.items():
        new = min(m + 1, INF)  # 이웃까지 1홉 추가
        cur = table.get(dst)
        if cur is None:
            if new < INF:
                table[dst] = (new, neighbor)  # 새 경로
        elif cur[1] == neighbor:
            table[dst] = (new, neighbor)  # 현 다음 홉 정보는 항상 반영
        elif new < cur[0]:
            table[dst] = (new, neighbor)  # 더 짧은 경로로 교체

def advertise(table, to_neighbor):  # 30초마다 전체 테이블
    # 포이즌 리버스: 그 이웃에게서 배운 경로는 16으로 광고
    return {d: (INF if nh == to_neighbor else m)
            for d, (m, nh) in table.items()}

routing-table.pseudocode:
class TrieNode:
    def __init__(self):
        self.child = {}  # '0' / '1' → 자식 노드
        self.next_hop = None

def insert(root, prefix_bits, next_hop):  # '1010…' 비트열
    node = root
    for b in prefix_bits:
        node = node.child.setdefault(b, TrieNode())
    node.next_hop = next_hop

def lookup(root, addr_bits):  # 최장 접두사 일치(LPM)
    node, best = root, root.next_hop  # /0 기본 경로
    for b in addr_bits:
        node = node.child.get(b)
        if node is None:
            break
        if node.next_hop is not None:
            best = node.next_hop  # 더 긴 일치로 갱신
    return best
